class QuantModelWidget:public QWidget {
 quantModel::Job job;quantModel::DailySchedule daily;QTimer dailyTimer;QCheckBox* dailyEnabled;QLineEdit *calendar;QLineEdit *python,*runner,*manifest,*watchlist;QComboBox* task;QPlainTextEdit *parameters,*reader;QListWidget* history;QLabel* status;QSpinBox* seconds;
 quint64 uiGeneration=0;QJsonObject settingsBaseline;QByteArray importPreview;QScrollArea* setupScroll;QPushButton* setupToggle;
 bool actionAllowed(const QWidget* origin=nullptr)const{return isVisible()&&isEnabled()&&!window()->isMinimized()&&QGuiApplication::applicationState()==Qt::ApplicationActive&&(!origin||(origin->isVisible()&&origin->isEnabled()));}
 void guard(std::function<void()> action){try{action();}catch(const std::exception& error){status->setText(QString::fromUtf8(error.what()));}}
 QJsonObject settings()const{return {{"python",python->text()},{"runner",runner->text()},{"manifest",manifest->text()},{"watchlist",watchlist->text()},{"task",task->currentData().toString()},{"parameters",parameters->toPlainText()},{"seconds",seconds->value()},{"calendar",calendar->text()},{"dailyEnabled",dailyEnabled->isChecked()}};}
 void saveSettings(){auto path=job.directory()+"/settings.json";QLockFile lock(path+".lock");quantModel::need(lock.tryLock(1000),"训练配置正在保存");auto current=QFileInfo::exists(path)?quantModel::object(quantModel::read(path,1024*1024)):QJsonObject{};quantModel::need(current==settingsBaseline,"另一页面已修改训练配置，请重新打开页面");auto next=settings();quantModel::write(path,next);settingsBaseline=next;}
 void refresh(){history->clear();for(auto value:job.records()){auto record=value.toObject();auto item=new QListWidgetItem(record.value("task").toString()+" / "+record.value("status").toString()+" / "+record.value("id").toString(),history);item->setData(Qt::UserRole,record.value("id"));}}
 void showRecord(QString id){auto record=job.reopen(id);setupScroll->hide();setupToggle->setText("展开研究配置");auto result=record.value("result").toObject();if(!result.isEmpty()){QJsonArray files;for(auto value:result.value("files").toArray()){auto file=value.toObject();auto path=file.value("path").toString();if(path=="request.json"||path.endsWith("/manifest.json")){auto original=quantModel::object(QByteArray::fromBase64(file.value("base64").toString().toLatin1()));result[path=="request.json"?"originalRequest":"originalDatasetManifest"]=original;}file.remove("base64");files.append(file);}result["files"]=files;record["result"]=result;}reader->setPlainText(QString::fromUtf8(QJsonDocument(record).toJson(QJsonDocument::Indented)));status->setText(record.value("status")=="completed"?"已重新核对完整结果与附件；模型精度仍需独立验证":"任务状态已保留；未完成任务不会自动重跑");}
 void tickDaily(){if(!settingsBaseline.value("dailyEnabled").toBool(false))return;guard([this]{auto decision=daily.inspect(settingsBaseline.value("calendar").toString(),settingsBaseline.value("manifest").toString(),QDateTime::currentDateTimeUtc(),job.active());if(decision.value("action")!="run"){if(!job.active())status->setText(decision.value("reason").toString());return;}daily.run(decision,[this,decision]{QJsonObject request{{"task","strategy-daily"},{"manifestPath",decision.value("manifestPath")},{"parameters",quantModel::object(settingsBaseline.value("parameters").toString("{}").toUtf8())},{"scheduled",true},{"scheduleDate",decision.value("date")},{"calendarSha256",decision.value("calendarSha256")}};job.start(settingsBaseline.value("python").toString(),settingsBaseline.value("runner").toString(),request,settingsBaseline.value("seconds").toInt(600));return job.current().value("id").toString();});});}
public:
 explicit QuantModelWidget(QString directory,QWidget* parent=nullptr):QWidget(parent),job(directory,this),daily(directory){
  auto layout=new QVBoxLayout(this);auto note=new QLabel("本机训练与预测 · LightGBM / MASTER / 因子 / 策略\n选择现有运行环境、模型程序和本地数据清单。每次使用独立数据副本；实验使用同一冻结数据。自选研究需8–120只证券及前复权数据。每日计划默认关闭；启用后应用运行期间按本地日历检查。在线采集与真实交易不执行。");note->setWordWrap(true);layout->addWidget(note);
  auto formPanel=new QWidget;auto form=new QFormLayout(formPanel);auto formScroll=new QScrollArea;setupScroll=formScroll;formScroll->setWidgetResizable(true);formScroll->setWidget(formPanel);formScroll->setMinimumHeight(140);formScroll->setMaximumHeight(380);layout->addWidget(formScroll,1);auto path=[&](QString label,QString name,QLineEdit*& field,QString filter){auto row=new QWidget;auto h=new QHBoxLayout(row);h->setContentsMargins(0,0,0,0);field=new QLineEdit;field->setObjectName(name);auto choose=new QPushButton("选择");h->addWidget(field,1);h->addWidget(choose);form->addRow(label,row);connect(choose,&QPushButton::clicked,this,[this,choose,field,label,filter]{if(!actionAllowed(choose))return;auto generation=uiGeneration;QPointer<QuantModelWidget> owner(this);auto selected=QFileDialog::getOpenFileName(this,label,{},filter);if(owner&&owner->uiGeneration==generation&&owner->actionAllowed()&&!selected.isEmpty())field->setText(selected);});};
  path("Python运行环境","quantModelPython",python,"Python (python.exe);;所有文件 (*)");path("模型程序 native_runner.py","quantModelRunner",runner,"Python (*.py)");path("数据清单 manifest.json","quantModelManifest",manifest,"JSON (*.json)");path("自选分组JSON（仅自选研究）","quantModelWatchlist",watchlist,"JSON (*.json)");path("本地交易日历catalog.json（仅每日计划）","quantModelCalendar",calendar,"JSON (*.json)");dailyEnabled=new QCheckBox("启用每日四策略：北京时间09:05后，交易日、本地数据≥1000只且不超过7天");dailyEnabled->setObjectName("quantModelDailyEnabled");form->addRow(dailyEnabled);
  task=new QComboBox;task->setObjectName("quantModelTask");for(auto pair:QList<QPair<QString,QString>>{{"LightGBM训练与预测","lightgbm"},{"MASTER训练与预测","master"},{"因子研究","factor"},{"原策略研究","strategy"},{"收盘信号扫描","signal"},{"三步模型实验","experiment"},{"自选分组本地四策略研究","watchlist"},{"每日四策略单次研究","strategy-daily"}})task->addItem(pair.first,pair.second);form->addRow("研究任务",task);
  parameters=new QPlainTextEdit("{}");parameters->setObjectName("quantModelParameters");parameters->setMaximumHeight(100);form->addRow("参数JSON（空对象使用原任务默认值）",parameters);seconds=new QSpinBox;seconds->setRange(5,3600);seconds->setValue(600);form->addRow("最长运行秒数",seconds);
  auto actionPanel=new QWidget;auto actions=new QHBoxLayout(actionPanel);auto actionScroll=new QScrollArea;actionScroll->setWidgetResizable(true);actionScroll->setWidget(actionPanel);actionScroll->setFixedHeight(68);layout->addWidget(actionScroll);auto button=[&](QString text,QString name,std::function<void()> action){auto b=new QPushButton(text);b->setObjectName(name);actions->addWidget(b);connect(b,&QPushButton::clicked,this,[this,b,action]{if(actionAllowed(b))guard(action);});};
  setupToggle=new QPushButton("收起研究配置");setupToggle->setObjectName("quantModelSetup");actions->addWidget(setupToggle);connect(setupToggle,&QPushButton::clicked,this,[this]{if(!actionAllowed(setupToggle))return;setupScroll->setVisible(!setupScroll->isVisible());setupToggle->setText(setupScroll->isVisible()?"收起研究配置":"展开研究配置");});
  button("开始本机研究","quantModelStart",[this]{saveSettings();QJsonObject request{{"task",task->currentData().toString()},{"manifestPath",manifest->text()},{"parameters",quantModel::object(parameters->toPlainText().toUtf8())}};if(task->currentData()=="watchlist")request["watchlist"]=quantModel::object(quantModel::read(watchlist->text(),1024*1024));job.start(python->text(),runner->text(),request,seconds->value());});
  button("取消任务","quantModelCancel",[this]{job.cancel();});button("预览结果包","quantModelImportPreview",[this]{quantModel::need(!job.active(),"先结束当前任务");auto generation=uiGeneration;QPointer<QuantModelWidget> owner(this);auto path=QFileDialog::getOpenFileName(this,"核验完整结果包",{},"JSON (*.json)");if(!owner||owner->uiGeneration!=generation||!owner->actionAllowed()||path.isEmpty())return;auto bytes=quantModel::read(path);auto result=quantModel::verifyBundle(bytes);importPreview=bytes;result.remove("files");reader->setPlainText(QString::fromUtf8(QJsonDocument(result).toJson(QJsonDocument::Indented)));status->setText("结果和附件摘要已核对，尚未保存；确认后独立归档");});button("确认结果导入","quantModelImportConfirm",[this]{quantModel::need(!importPreview.isEmpty(),"没有待确认结果");auto id=job.importBundle(importPreview);importPreview.clear();refresh();showRecord(id);});button("取消预览","quantModelImportCancel",[this]{importPreview.clear();reader->clear();status->setText("结果预览已取消");});button("刷新历史","quantModelRefresh",[this]{refresh();});button("允许今日重试","quantModelDailyRetry",[this]{daily.allowRetry(QDateTime::currentDateTimeUtc(),job.active());tickDaily();});button("导出已核对结果包","quantModelExport",[this]{auto item=history->currentItem();quantModel::need(item,"先选择已完成记录");auto id=item->data(Qt::UserRole).toString();auto record=job.reopen(id);quantModel::need(record.value("status")=="completed","任务未完成");auto generation=uiGeneration;QPointer<QuantModelWidget> owner(this);auto path=QFileDialog::getSaveFileName(this,"导出可离线复核的完整结果包",{},"JSON (*.json)");if(owner&&owner->uiGeneration==generation&&owner->actionAllowed()&&!path.isEmpty())quantModel::write(path,quantModel::read(job.directory()+"/"+id+"/verified-result.json"));});
  history=new QListWidget;history->setObjectName("quantModelHistory");history->setMaximumHeight(100);layout->addWidget(history);reader=new QPlainTextEdit;reader->setReadOnly(true);reader->setObjectName("quantModelReader");layout->addWidget(reader,1);status=new QLabel;status->setObjectName("quantModelStatus");status->setWordWrap(true);layout->addWidget(status);
  connect(history,&QListWidget::itemClicked,this,[this](QListWidgetItem* item){if(!actionAllowed(history))return;guard([this,item]{showRecord(item->data(Qt::UserRole).toString());});});
  job.changed=[this](QJsonObject record){status->setText(record.value("status").toString()+" · "+record.value("progress").toObject().value("event").toObject().value("message").toString()+" "+record.value("error").toString());if(QStringList{"completed","failed","cancelled"}.contains(record.value("status").toString()))guard([this,record]{daily.finished(record);refresh();});};job.failed=[this](QString message){status->setText(message);};
  guard([this]{auto path=job.directory()+"/settings.json";if(QFileInfo::exists(path)){settingsBaseline=quantModel::object(quantModel::read(path,1024*1024));python->setText(settingsBaseline.value("python").toString());runner->setText(settingsBaseline.value("runner").toString());manifest->setText(settingsBaseline.value("manifest").toString());watchlist->setText(settingsBaseline.value("watchlist").toString());task->setCurrentIndex(std::max(0,task->findData(settingsBaseline.value("task"))));parameters->setPlainText(settingsBaseline.value("parameters").toString("{}"));seconds->setValue(settingsBaseline.value("seconds").toInt(600));calendar->setText(settingsBaseline.value("calendar").toString());dailyEnabled->setChecked(settingsBaseline.value("dailyEnabled").toBool(false));}else python->setText(qEnvironmentVariable("WEBSTOCK_QUANT_PYTHON"));refresh();});connect(dailyEnabled,&QCheckBox::toggled,this,[this](bool enabled){if(!actionAllowed(dailyEnabled)){QSignalBlocker blocker(dailyEnabled);dailyEnabled->setChecked(settingsBaseline.value("dailyEnabled").toBool(false));return;}try{saveSettings();if(!enabled&&job.current().value("scheduled").toBool())job.cancel();}catch(const std::exception& error){QSignalBlocker blocker(dailyEnabled);dailyEnabled->setChecked(settingsBaseline.value("dailyEnabled").toBool(false));status->setText(QString::fromUtf8(error.what())+"；开关未保存，仍使用已保存状态");}});dailyTimer.setInterval(60000);connect(&dailyTimer,&QTimer::timeout,this,[this]{tickDaily();});dailyTimer.start();QTimer::singleShot(0,this,[this]{tickDaily();});
 }
 ~QuantModelWidget()override{job.changed={};job.failed={};job.cancel();}
 void cancel(){job.cancel();}
 void leave(){++uiGeneration;importPreview.clear();if(!job.current().value("scheduled").toBool())job.cancel();}
protected:
 void hideEvent(QHideEvent* event)override{leave();QWidget::hideEvent(event);}
};
